-- Rifts World Book 8: Japan - its bestiary and its notable NPCs.
-- 6 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~100-japan-race-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 creatures are in' AS assertion, count(*) AS got, 6 AS want
  FROM creatures WHERE slug IN ('tengu', 'oni-of-the-one-hundred', 'sura-kappa', 'dragon-hatchling-shikome-kido-mi', 'dragon-hatchling-kumo-mi', 'dragon-hatchling-asama-tatsu');
SELECT 'and 6 of them are playable' AS assertion, count(*) AS got, 6 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('tengu', 'oni-of-the-one-hundred', 'sura-kappa', 'dragon-hatchling-shikome-kido-mi', 'dragon-hatchling-kumo-mi', 'dragon-hatchling-asama-tatsu');
SELECT 'the creatures carry 31 attacks' AS assertion, count(*) AS got, 31 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('tengu', 'oni-of-the-one-hundred', 'sura-kappa', 'dragon-hatchling-shikome-kido-mi', 'dragon-hatchling-kumo-mi', 'dragon-hatchling-asama-tatsu');

