INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('tengu', 'Tengu', 'faerie', 'rifts', 1, 'Any; about 3% principled, 12% scrupulous, 20% unprincipled, 30% anarchist, 5% aberrant, 20% miscreant and 10% diabolic', '{"IQ":"3D6+1","ME":"2D6+14","MA":"2D6+10","PS":"3D6+12","PP":"2D6+12","PE":"2D6+12","PB":"2D6","Spd":"3D6+20"}', NULL, NULL, '3D4x10+PE', '4D4x10', NULL, 'M.D.C. (natural) is 3D4x10 plus the P.E. number, +2D6 per level of experience. No Hit Points: a mega-damage creature. P.P.E. is 4D4x10, +2D6 per level. The stored Spd is running; flying Spd is 1D4x10+48 (40 to 60 mph / 64 to 96 km). Regenerates 3D6 M.D. per hour.', NULL, 10, '{"attacks":2,"dodge":2,"pull":2,"disarm":1,"roll":4}', 'R.C.C. bonuses (p.68): +3 to save vs Horror Factor, +2 vs magic of any kind, +2 vs mind control of any kind, +5 vs possession, +4 vs poison, +8 vs disease and radiation. The combat figures stored are Teng-jutsu at level one (p.69): two attacks per melee, +2 dodge, +2 pull punch or kick, +1 disarm, +1 roll with punch/fall/impact, +3 maintain balance, +1 break fall; roll 4 adds the +3 roll from Tengu Acrobatics. Teng-jutsu by level: 2 drop kick, +1 initiative, +2 back flips; 3 +1 strike, +1 disarm, +1 leap dodge; 4 +1 attack; 5 critical strike (double damage) from kicks, jump kicks and leap attacks; 6 +1 roll, +2 pull, +1 leap dodge; 7 +1 initiative, leg hook and backward sweep; 8 +1 attack; 9 +2 disarm, +1 back flips, +1 cartwheel attack; 10 axe kick, +1 initiative, +1 parry; 11 +1 attack; 12 +1 leap dodge, +1 disarm; 13 snap kick and wheel kick; 14 +1 pull, +1 leap dodge; 15 +1 attack. Leap dodge is +2 plus P.P. bonus; a timed leap gets only +2 and the P.P. bonus. The Power Kick is 4D6 M.D. in the Damage list (p.68) and 5D6 M.D. in the Teng-jutsu text (p.70).', 'R.C.C. skills: Go (+15%), Concealment (+20%), Palming (+10%), Imitate Voice (+8%), Intelligence (+10%), Land Navigation (+10%), speaks Faerie, traditional Japanese and Dragonese at 98%, literate in traditional Japanese and Dragonese/Elf (+20%), Lore: Demons & Monsters (+10%), Lore: Magic (+10%), Math: Basic (+20%), Tracking (+10%, humanoids and animals), Wilderness Survival (+10%), W.P. Sword, W.P. Blunt, Hand to Hand: Teng-jutsu. Four related skills, plus one more at levels 3, 6, 9 and 12: Communications radio basic only; Domestic (+10%); Espionage (+5%); Medical first aid or holistic medicine only; Physical any except acrobatics and gymnastics; Rogue (+10%); Science (+5%); Technical (+10%) except computers or tech skills; W.P. ancient only; Wilderness (+10%); no Electrical, Mechanical, Military, Pilot or Pilot Related. Two secondary skills at each of levels 1, 3, 5 and 10. Tengu Acrobatics: balance 50% +4% per level, climb rope/rappel 40% +4% per level, walk tightrope 40% +4% per level.', 'Winged flight. Nightvision to 500 feet (152 m), sees the invisible, senses supernatural beings at 80% within 20 feet (6 m). Ordinary fire and heat cannot hurt it, while magical and mega-damage fire or heat deal half. Tires at a tenth of the human rate. Shape-change into a human up to three times in 24 hours, 12 hours per level each time: always an Asian-looking person of its own sex, 3 to 6 feet (0.9 to 1.8 m) tall and 30 to 300 lbs (13.6 to 136 kg), wings gone. Possess Others: it may speak through a host who consents, or who is asleep, unconscious or in a trance, for one minute per level at up to 50 feet (15.2 m) +5 feet (1.5 m) per level; it gains the host''s languages and no other control. Teng-jutsu powers: Tengu Leap of 10 feet (3 m) high from a standstill, +2 feet (0.6 m) per later level, with a run-up adding 20 feet (6 m) of length; the leap doubles as an automatic dodge that costs one melee attack each time; a timed leap makes a foe''s missed blow land on something else; kicks add 1D6 M.D.; and it can hold a one-legged balance for ten minutes per level, with no attack, parry or dodge meanwhile.', 'Knows as incantations: Globe of Daylight, Heavy Breathing, Ignite Fire, Fuel Flame, Energy Disruption, Wind Rush, Summon Rain and Calm Storm. One more first or second level spell at levels 3, 6, 9, 12 and 15, usually elemental in nature.', 'None', '4 to 5 feet (1.2 to 1.5 m) as a tengu; up to 6 feet (1.8 m) in human guise', '120 to 180 pounds (54 to 82 kg)', 'Up to 800 years; seldom appears to age', 'Forested mountains of Japan, and also the mountains of Korea, China and India; unknown in Europe and the Americas. An estimated 1000 live along Tengu Road on Mt. Kurama.', 'Humble farmers, yamabushi, Shinto priests and those who reject technology; many gods and spirits of the Japanese pantheons; dragons, great warriors, scholars and philosophers', 'The Chinese Celestial Dogs, the gods and minions of China and India, and most demons; dislikes technology and those who worship it or destroy nature with it. Fears demon quellers.', 'An R.C.C. with its own skills; no O.C.C. is offered. The book presents it as a good player character and an equally good NPC villain. A player character knows only Teng-jutsu; NPCs usually know one more martial art (any but samurai and ninjitsu), and NPCs of level six or higher may know a second, mortal style without its mystic powers at half their level. No bionics or cybernetics. Starts with a robe or tunic, belt, sandals, bedroll, sacks, a water skin, one sword (katana or wakizashi) and/or a club or staff; no starting money is printed. Average NPC level 2D4.', 'The winged mountain goblin of Japan, counted among the faerie folk: a short, wiry, muscular humanoid with golden or amber eyes, heavy brows, wings at the shoulders and either a beak or a huge pointed nose; skin pale pink, white or blue, feathers dark blue, black or dark red. Notorious pranksters who bait Buddhist priests and anyone leaning on technology, yet respectful of true samurai, mystic ninja, Shinto priests and above all the yamabushi.', 'Rifts World Book 8: Japan p.66-70'),
('oni-of-the-one-hundred', 'Oni of the One Hundred (Lesser Oni)', 'demon', 'rifts', 1, '45% miscreant, 30% diabolic, 5% aberrant, 15% anarchist and 5% other', '{"IQ":"2D6","ME":"2D6","MA":"2D6","PS":"2D6+22","PP":"2D6+12","PE":"2D6+16","PB":"1D6","Spd":"6D6"}', NULL, NULL, '2D6x10+40', '5D6', NULL, 'M.D.C. is 2D6x10+40, plus whatever the Other Features table adds (0 to 35). P.P.E. 5D6 is for a typical warrior. All attributes are supernatural. Spd is NOT a fixed roll: the Oni Legs table (p.201) sets it - 5D6 for human legs (01-15), 4D6 monkey legs (16-25), 6D6+10 classic oni legs (26-50), 6D6 for the four results from 51 to 90, 3D6 for a snail-like trunk (91-00); 6D6 is stored as the commonest result. Horror Factor 11 is the base; the Oni Head Shape table adds 0 to +4. Nine random tables (p.201-202) are rolled once each to build one oni: General Body Shape, Head Shape, Nose, Eyes, Mouth, Arms & Hands, Legs, Other Features, Skin Color - and the Magic line has its own percentile table of four power groups. They are summarised here and in natural_abilities, not expanded. Regenerates 2D6 M.D. per hour.', NULL, 11, '{"attacks":4,"initiative":1,"strike":2,"parry":2,"dodge":2,"pull":2,"roll":1}', 'On top of physical attribute bonuses; also +6 to save vs Horror Factor. Four attacks per melee, plus one at level 6 and one at level 12. Table results can add more: a third arm or five arms each give +1 attack per melee, tentacle arms +4 to entangle/grab/hold, monkey legs +10% to balance and climbing, a snail trunk +4 to maintain balance.', 'R.C.C. skills (very limited): Intelligence (+4%), Track Humanoids (+10%), Land Navigation (+15%), Climb (+10%), Swim (+10%), W.P. Blunt, W.P. Sword and two W.P.s of choice (any); speaks Japanese, Gobblely and Faerie at 98% and can learn two other languages (+10%). Four secondary skills from espionage, physical, technical, rogue and wilderness, at base level.', 'Nightvision to 500 feet (152 m), working in total darkness too. Fire and cold do half damage, disease cannot touch it. No two look alike: the creation tables on p.201-202 give each one a body shape (human, skeletal, blob, toad, bird, fish, or an 8 foot / 2.4 m giant growing 1D4 feet more), a head shape that raises Horror Factor, and a nose, eyes, mouth, arms, legs, an extra feature and a skin color. Three of those tables carry combat figures: the mouth sets the bite (from a single point of M.D. up to 3D6 M.D.), the arms set the hand strike (1D4 to 3D6 M.D., or a 2D6 M.D. tentacle whip), and horns from Other Features give a head butt of 1D4 or 2D6 M.D. Other Features can also add 5 to 35 M.D.C. for scales, fur, boils and the like.', 'Not spell casters: one of four sets of natural powers, chosen or rolled (p.202), usable up to 8 times per 24 hours in all. 01-25: Fear, Compulsion, Luck Curse, Minor Curse, Repel Animals, Tongues. 26-50: Befuddle, Blind, Sickness, Spoil (food & water), Animate/Control Dead, Tongues. 51-75: Globe of Daylight, Ignite Fire, Cloud of Smoke, Fire Ball, Fool''s Gold, Tongues. 76-00: Breathe Without Air, Fly as the Eagle, Wind Rush, Summon Fog, Summon Storm, Tongues.', 'None', 'Average 4 to 5 feet (1.2 to 1.5 m) tall; the giant body shape is 8 feet (2.4 m) +1D4 feet', '100 to 250 pounds (45 to 112.5 kg)', '250+ years', 'Japan, Taiwan, Korea, China and parts of India and Southeast Asia, reaching islands as far as the Philippines; wilderness, mountains, slums, sewers and ruins. In Japan mostly The Zone and the Freelands. War bands run from 1D6+4 to 3D6+12 and rarely above 80; clans from 20-40 up to 300-500; a village holds 3D4x100 oni with other supernatural creatures, allies and slaves.', 'Other oni and demons, vampires, goblins, goblin spiders, ogres, trolls, gargoyles, evil dragons, priests and sorcerers, and powerful evil of every kind; the Horune pirates have traded with them for decades', 'Tengu, yamabushi, bishamon, demon quellers, samurai, psi-stalkers, Atlantean Undead Slayers and a handful of gods. Faerie folk, elementals, dragons and the kilin are disliked and avoided. The people of Japan, human and D-Bee, count all oni as deadly enemies.', 'An R.C.C. with its own skills; no O.C.C. is offered. The book calls these primarily NPC villains and leaves a player character wholly to the G.M.; such a character is probably an outcast, perhaps for being anarchist, unprincipled or scrupulous. Average NPC warrior is third level, elite warriors 1D4+2, a war chief or clan leader 1D4+4. One oni in ten is an oni master (a separate entry). No starting gear or money is printed; most fight with tooth and claw, and fewer than 15% rely on human armor and energy weapons.', 'The commonest demons of Japan: dull-witted, vindictive, usually small goblin-like monsters that raid in tribal war bands, enslave villages and eat what they kill, human flesh by preference. Bold in numbers but often routed once their strongest few are beaten. They respect only power and follow whichever warrior or magic user is strongest. Many have horns, shaggy manes and big two-toed clawed feet.', 'Rifts World Book 8: Japan p.199-203'),
('sura-kappa', 'Sura-Kappa', 'humanoid', 'rifts', 1, 'Typically unprincipled or aberrant, but can be any', '{"IQ":"3D6","ME":"2D6","MA":"2D6","PS":"3D6+6","PP":"3D6+2","PE":"3D6+12","PB":"2D6","Spd":"4D6"}', NULL, NULL, '2D4x10', '6D6+40', NULL, 'M.D.C. is 2D4x10. P.P.E. is 6D6+40, +1D6 per level of experience. The stored Spd is running; swimming Spd is 4D6x10. Attributes are supernatural. Regenerates 2D6 M.D. per minute in water. If the water in its head-bowl spills, the M.D.C. turns into ordinary hit points open to S.D.C. attacks until it is put back in water.', NULL, 10, '{"attacks":4,"initiative":1,"strike":1,"parry":2,"dodge":2,"roll":4}', 'On top of physical attribute bonuses; also +2 to save vs psionics and +5 to save vs Horror Factor. Four attacks per melee round, or two by magic. With the head water spilled: one action per melee, Spd one-tenth, P.S. 4 and no natural abilities; five minutes back in water restores everything.', 'R.C.C. skills: Fishing (+20%), Wilderness Survival (+15%), First Aid (+15%), Holistic Medicine (+10%), Prowl (+10%), Climb (+10%), W.P. Club, one W.P. of choice (ancient only); speaks Faerie Speak (Kappa), Japanese and Gobblely at 98% and can learn one other language (+10%). Swim 98% and recognize species of fish 80% are natural abilities. Three secondary skills from espionage, physical, technical, rogue and wilderness, at base level.', 'Nightvision to 300 feet (91 m). Swims at 98%, breathes water as easily as air, never gets the bends, and tolerates depths down to one mile (the metric figure is printed as 1.6 m). Knows a fish''s species at 80%. Cold deals half damage. A healing touch mends 2D6 hit points or M.D. and works once in any five minutes. Weakness: it must stay wet, and on land it carries water in the hollow on its skull; spill that and it drops helpless at once.', 'Ocean Magic (Rifts Underseas p.64-71): Air Swim, Calm Waters, Communicate with Sea Creatures, Impervious to Ocean Depths, Ride the Waves, Weed Snare, Water Seal, Water Pulse, Water Rush and Water Spout.', 'None', '3 feet (0.9 m)', '80 pounds (36 kg)', '80 to 100 years', 'Rivers, lakes and coasts; most common in the Sea of Japan and the East China Sea, scattered across the South Pacific. Family groups of up to about 20, sometimes gathered in communities of thousands; ranges up to 20 miles (32 km) inland along rivers.', 'None as such; little contact outside the family group. A few side with oni, the Lord of the Deep and other dark forces.', 'Anything that enters its territory or attacks it. Hates the Lord of the Deep and its minions; dislikes Horune pirates, the Naut''Yll and most sea monsters; wary of Lemurians, amphibs and other intelligent sea life except dolphins and other cetaceans.', 'An R.C.C. with its own skills; no O.C.C. is offered and, unlike the oni entries beside it, no NPC-only caveat is printed. Average NPC level 1D4+1. No starting gear or money is printed; kappa scorn human technology and live as tribal hunters.', 'A small D-Bee of Japan''s waters, about as big as a child of eight: a hairless, gangly, monkey-like body with greenish-yellow skin, webbed hands and feet, fins along the forearms and legs, and a bowl-shaped hollow on top of the head that holds water while it is ashore. Banished with the oni in ancient times and back since the Rifts. Usually civil and talkative, sometimes helpful to sailors, but ruthless toward intruders and willing to eat humanoids.', 'Rifts World Book 8: Japan p.205-206'),
('dragon-hatchling-shikome-kido-mi', 'Shikome Kido-Mi Dragon (Hatchling)', 'dragon', 'rifts', 1, 'The species is typically miscreant or diabolic, occasionally anarchist or miscreant', '{"IQ":"3D6+10","ME":"3D6+10","MA":"3D6+6","PS":"2D6+32","PP":"3D6+10","PE":"3D6+10","PB":"3D6+10","Spd":"6D6"}', NULL, NULL, '1D4x100+50', '1D4x100', '3D6x10', 'Hatchling figures stored. M.D.C. is 1D4x100+50 for a hatchling (1D4x1000+800 young adult, 2D4x1000+200 mature adult). P.P.E. is 1D4x100 for a hatchling (1D6x100+150 young adult, 2D4x100+300 mature adult; the Magic line prints 2D4x100). I.S.P. 3D6x10 and the attribute dice are printed once for the species, with no hatchling figure. Spd is running and climbing. All attributes are supernatural. Regenerates 1D4x10 M.D.C. per minute.', NULL, 16, '{"attacks":4,"initiative":3,"strike":1,"parry":1,"dodge":2,"roll":2}', 'On top of physical attribute bonuses; also +8 to save vs Horror Factor and +2 on all saving throws. A hatchling has four physical attacks per melee - half the mature adult''s eight (a young adult has six) - or two by magic. Vulnerabilities: silver weapons do mega-damage, fire does normal damage, and magic weapons (the living samurai sword, rune weapons, Millennium Tree weapons) do double damage. The Damage line is printed once for the species; no separate hatchling damage is given.', 'R.C.C. skills it is likely to know: Palming (+10%), Streetwise (+12%), Detect Concealment (+10%), Intelligence (+10%), Camouflage (+15%), Calligraphy (+10%), Forgery (+10%), Bonsai (+20%), Go (+10%), Japanese Mythology (+20%), Demon & Monster Lore (+20%), W.P. Sword, W.P. Blunt and one W.P. of choice (any); speaks Japanese, Dragonese/Elf and Gobblely at 98% and can learn two other languages (+10%). Natural abilities: climbing 98%, prowl 60%, track by blood scent 78%, recognize a creature by scent 68% (-30% for a specific individual), dimensional teleport 88%.', 'Nightvision to 1200 feet (366 m), even with no light at all, and sees the invisible. Turns invisible whenever it likes, changes its own length at will, and can teleport between dimensions. Cold, poison, disease and possession have no effect on it. It knows every mystic martial arts power (invisibility, body hardening and zenjoriki) yet can use none of them; it teaches them to minions and to those who do it special services, seldom more than three per pupil.', 'Printed for the grown dragon: 70% know all spell magic of levels 1-8 plus all dimensional magic spells, Sanctum, Talisman, Amulet, Create Zombie and Create Mummy; 29% know all Temporal Raider magic (Rifts England) plus all spell magic of levels 1-3 and all dimensional magic spells; 1% know all spells of levels 1-5 and the secrets of tattoo magic. 40% can also make elemental shurikens, the 10,000 strength nunchaku and powders for the Holy Incense Burner. A hatchling player character follows the Rifts RPG hatchling rules for magic instead.', 'Limited to Clairvoyance, See Aura, Sense Magic, Sixth Sense, Telepathy, Death Trance, automatic mind block defense and Hypnotic Suggestion', 'Species: any length from 12 feet (3.6 m) to its full 42 feet (12.8 m), snout to tail tip. No hatchling size is printed.', 'Species: one to three tons', '8000 years', 'Native to an alien dimension. Found anywhere but favors Japan, Korea, China, India and Indonesia; keeps mountain retreats or rules villages and even cities from a castle.', 'None in the true sense; at best an accomplice, more often minions, servants and slaves, which may include oni, wizards and ninja. Occasionally associates with other supernatural beings.', 'Treats everyone as a rival, other shikome kido-mi and gods included. Demon quellers count it among the demons to destroy.', 'The book calls dragons ideal NPCs and villains; where a player character is allowed it uses the hatchling R.C.C. rules of the Rifts RPG and starts as a first level hatchling. No O.C.C. is offered. NPC level averages 1D4+3 (hatchling or young adult) and 2D4+5 (mature adult).', 'The young of the dragon whose name means hideous sorcery serpent: a long, scaled, whiskered serpent-dragon with clawed limbs. The species is a scheming sorcerer that tempts mortals with arcane secrets in order to corrupt and control them, bows to no one, and is said in legend to have taught the ninja clans their arts of invisibility. When angry it rears up on its hind legs and tends to swell toward full size.', 'Rifts World Book 8: Japan p.211-212'),
('dragon-hatchling-kumo-mi', 'Kumo-Mi, Cloud Dragon (Hatchling)', 'dragon', 'rifts', 1, 'Any; kumo-mi can be good, anarchist or evil', '{"IQ":"3D6+10","ME":"3D6+10","MA":"2D6+15","PS":"2D6+28","PP":"3D6+8","PE":"3D6+12","PB":"3D6+10","Spd":"3D6+88"}', NULL, NULL, '1D4x100+50', '1D4x100', '3D4x10', 'Hatchling figures stored. M.D.C. is 1D4x100+50 for a hatchling (1D4x1000+600 young adult, 2D4x1000+100 mature adult). P.P.E. is 1D4x100 for a hatchling (1D6x100+80 young adult, 1D6x100+200 mature adult). I.S.P. 3D4x10 and the attribute dice are printed once for the species, with no hatchling figure. Spd is flying, snaking through the sky at over 55 mph (88 km); no ground speed is printed. All attributes are supernatural. Regenerates 1D4x10 M.D.C. per minute.', NULL, 15, '{"attacks":4,"initiative":3,"strike":1,"parry":1,"dodge":4,"roll":3}', 'On top of physical attribute bonuses; also +7 to save vs Horror Factor and +2 on all saving throws. Horror Factor is printed as awe. A hatchling has four physical or psionic attacks per melee (a young adult six, a mature adult seven), or two by magic. Vulnerabilities: silver weapons do mega-damage, fire and magic weapons do their normal damage, and earth elementals inflict double damage. The Damage line is printed once for the species; no separate hatchling damage is given.', 'R.C.C. skills, scholarly pursuits only: all technical skills (including all lores, languages and literacy) except computers and photography, all at +10%; also Basic Math (+10%), Calligraphy, Land Navigation, Identify Plants and Fruits, Gardening, Dance, Sing and Play Wind Instruments (flutes and horns). Natural abilities: climbing 98%, prowl 60%, dimensional teleport 88%.', 'Flies without wings. Nightvision to 1200 feet (366 m), even with no light at all, and sees the invisible. Turns invisible whenever it likes, changes its own length at will, and can teleport between dimensions. Cold, poison, disease and possession have no effect on it. Mystic martial arts: it chooses a single invisibility art plus a single zenjoriki power.', 'Printed for the grown dragon: 50% know all air, illusion and dimensional magic spells listed in the Rifts RPG, plus Tongues, Magic Pigeon, Eyes of Thoth, Sanctum, Dispel Magic, Negate Magic, Anti-Magic Cloud and both protection circles; the other 50% know all air warlock spells (Rifts Conversion Book One). A hatchling player character follows the Rifts RPG hatchling rules for magic instead.', 'All healing abilities plus Telepathy, Empathy and Mind Block', 'Species: any length from 15 feet (4.6 m) to its full 60 feet (18.3 m), snout to tail tip. No hatchling size is printed.', 'Species: four tons', '8000+ years', 'Native to an alien dimension. Found anywhere but favors Japan, Korea, China, India and Indonesia, high in the mountains; some rule villages or cities from a castle. No more than 100 live in the Japanese island chain.', 'Depends on the dragon''s alignment, temper and goals: some are kind to humans, some aloof, some cruel and controlling. Most are drawn to intelligent, trustworthy beings and practitioners of magic, and tend to avoid other dragons.', 'Often clashes with elementals and with power-hungry creatures of magic and supernatural beings', 'The book calls dragons ideal NPCs and villains; where a player character is allowed it uses the hatchling R.C.C. rules of the Rifts RPG and starts as a first level hatchling. No O.C.C. is offered. NPC level averages 1D4+2 (hatchling or young adult) and 2D4+4 (mature adult).', 'The young of the cloud serpent, a wingless dragon of the high mountains with elemental powers that swims through the air like an eel and seldom lands. Fine scales, usually white with green accents and jade whiskers and fins, or pale blue with green or dark blue fins; diamond-bright eyes, two long horns, and a single pair of clawed limbs near the front. As varied in character as humans: some gentle guardians, some tyrants.', 'Rifts World Book 8: Japan p.212-214'),
('dragon-hatchling-asama-tatsu', 'Asama-Tatsu/Dragon (Hatchling)', 'dragon', 'rifts', 1, 'Any; good, anarchist or evil', '{"IQ":"2D6+16","ME":"2D6+10","MA":"2D6+10","PS":"2D6+36","PP":"2D6+10","PE":"2D6+16","PB":"3D6+10","Spd":"3D6+88"}', NULL, NULL, '1D4x100+50', '1D4x100', '3D4x10', 'Hatchling figures stored. M.D.C. is 1D4x100+50 for a hatchling (1D6x1000+600 young adult, 2D4x1000+1400 mature adult). P.P.E. is 1D4x100 for a hatchling (1D6x100+100 young adult, 2D4x100+200 mature adult). I.S.P. 3D4x10 and the attribute dice are printed once for the species, with no hatchling figure. Spd is flying, snaking through the sky at over 55 mph (88 km); no ground speed is printed. All attributes are supernatural. Regenerates 1D4x10 M.D.C. per minute.', NULL, 16, '{"attacks":4,"initiative":4,"strike":2,"parry":2,"dodge":2,"roll":2}', 'On top of physical attribute bonuses; also +8 to save vs Horror Factor and +2 on all saving throws. Horror Factor is printed as awe. A hatchling has four physical or psionic attacks per melee (a young adult six, a mature adult seven), or two by magic. Vulnerabilities: cold-based attacks and magic do double damage; magic weapons and mega-damage weapons do their normal damage. The Damage line is printed once for the species; no separate hatchling damage is given.', 'R.C.C. skills, scholarly pursuits only: all science and technical skills, including computers, and all pilot related skills or medical and herbal skills; all at +20%. Natural abilities: climbing 90%, swimming 90%, dimensional teleport 92%, teleport self 96%.', 'Flies without wings. Nightvision to 1200 feet (365 m), even with no light at all, and sees the invisible. Fire and heat of any kind do nothing to it, M.D. plasma and magic fire included; poison, disease and possession likewise. Changes its own length at will and can teleport itself and between dimensions. Mystic martial arts: one zenjoriki power at each of levels 2, 7, 12 and 20.', 'Printed for the grown dragon: 50% are ley line walkers who know all spells of levels 1-7 plus 12 more from levels 8-15; 20% are diabolists (Rifts Conversion Book One); 20% are techno-wizards who know all spells of levels 1-5 plus six of choice from higher levels; 10% are alchemists (NPCs) able to make every item in the magic section except rune weapons. A hatchling player character follows the Rifts RPG hatchling rules for magic instead.', 'All physical abilities plus Telepathy, Pyrokinesis, Mind Block Auto-Defense and P.P.E. Shield', 'Species: 20 feet (6 m) tall at the head and 100 feet (30.5 m) long at full size; the Size line gives the smallest length as 15 feet (4.6 m), Natural Abilities as 20 feet (6 m). No hatchling size is printed.', 'Species: twenty-two tons', '8000+ years', 'Native to an alien dimension. Found anywhere but favors Japan, Korea, China, India and Indonesia; keeps mountain retreats and is reputed to live inside volcanoes, though some rule villages or cities from a castle.', 'Depends on the dragon''s alignment, temper and goals: some are kind to humans, some aloof, some cruel and controlling. Most are loners that avoid other dragons; a few join monasteries to teach the monks.', 'Often clashes with power-hungry creatures of magic and supernatural beings', 'The book calls dragons ideal NPCs and villains; where a player character is allowed it uses the hatchling R.C.C. rules of the Rifts RPG and starts as a first level hatchling. No O.C.C. is offered. NPC level averages 1D4+2 (hatchling or young adult) and 2D4+5 (mature adult).', 'The young of the volcano dragon, a huge wingless serpent-dragon with scales that look like gold, silver eyes, a golden unicorn horn, a golden-red mane and dark crimson or black fins down the spine. The species is learned, mostly aloof, proof against fire and quick to explode when pushed too far; it would rather use magic but fights ferociously when angered or cornered.', 'Rifts World Book 8: Japan p.214-215');
INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'tengu', 'Beak strike, peck, bite or head butt', '2D4', 0, NULL, 'S.D.C.', 0),
('creature', 'tengu', 'Restrained punch or kick', '4D6', 0, NULL, 'S.D.C., plus P.S. bonus', 1),
('creature', 'tengu', 'Full strength punch', '1D4', 1, NULL, NULL, 2),
('creature', 'tengu', 'Full strength kick', '1D6', 1, NULL, NULL, 3),
